/**
 * `util.PathJoinRelX` port (modules/util/path.go:74–83) for a single path
 * element: backslashes read as slashes, dot segments resolved, empty → ".".
 * ("..", "/", "a/../.." all reduce to "."; "../C" → "C".)
 */
function pathJoinRelX(name: string): string {
  const stack: string[] = [];
  for (const part of name.replace(/\\/g, "/").split("/")) {
    if (part === "" || part === ".") {
      continue;
    }
    if (part === "..") {
      stack.pop();
      continue;
    }
    stack.push(part);
  }
  return stack.length === 0 ? "." : stack.join("/");
}

/**
 * Bind the MarkupOption payload the way Go's `bind(api.MarkupOption{})` does
 * (routers/api/v1/api.go:1022): case-insensitive key matching, absent fields
 * are zero values, malformed payloads → 422 validationError (api.go:841–844).
 * Same standalone-bind posture as routes/markdown.ts.
 */
function bindMarkupOption(raw: string): { text: string; mode: string; context: string; wiki: boolean } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new ApiError(422, "invalid request body");
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new ApiError(422, "invalid request body");
  }
  const source = parsed as Record<string, unknown>;
  const option: Record<string, unknown> = {};
  for (const [rawKey, value] of Object.entries(source)) {
    const key = MARKUP_OPTION_KEYS.find((candidate) => candidate.toLowerCase() === rawKey.toLowerCase());
    if (key !== undefined) {
      option[key] = value;
    }
  }
  const schema = markupOptionSchema.safeParse(option);
  if (!schema.success) {
    throw new ApiError(422, "invalid request body");
  }
  return {
    text: schema.data.Text ?? "",
    mode: schema.data.Mode ?? "",
    context: schema.data.Context ?? "",
    wiki: schema.data.Wiki ?? false,
  };
}

/** Contract keys of MarkupOption (Go field names, no json tags). */
const MARKUP_OPTION_KEYS = ["Context", "FilePath", "Mode", "Text", "Wiki"] as const;

/** Route registration hook for the declared JSON body: upstream answers bind
 *  failures with 422 (api.go:841–844) — map the validator's default 400 onto
 *  the error family (routes/markdown.ts convention). */
const markupBodyHook = ({ success }: { success: boolean }): undefined => {
  if (!success) {
    throw new ApiError(422, "invalid request body");
  }
  return undefined;
};

