/** Upstream's fixed implementation note (licenses.go:68–69). */
const LICENSE_IMPLEMENTATION_NOTE =
  "Create a text file (typically named LICENSE or LICENSE.txt) in the root of your source code and copy the text of the license into the file";

export function registerMiscT2Routes(
  app: OpenAPIHono<ApiEnv>,
  requireAuth: MiddlewareHandler<ApiEnv>,
): void {
  // GET /gitignore/templates — ListGitignoresTemplates (gitignore.go:16–28):
  // the sorted name list (GitignoreTemplateList = array of string).
  app.openapi(
    createRoute({
      method: "get",
      path: "/gitignore/templates",
      tags: ["miscellaneous"],
      summary: "Returns a list of all gitignore templates",
      operationId: "listGitignoresTemplates",
      request: {},
      responses: {
        200: {
          description: "GitignoreTemplateList",
          content: { "application/json": { schema: z.array(z.string()) } },
        },
      },
    }),
    (c) => c.json(Object.keys(GITIGNORE_TEMPLATES), 200),
  );

  // GET /gitignore/templates/{name} — GetGitignoreTemplateInfo
  // (gitignore.go:30–46): PathJoinRelX'd name, options.Gitignore read,
  // APIErrorNotFound on a miss.
  app.openapi(gitignoreTemplateInfoRoute, (c) => {
    const name = pathJoinRelX(c.req.valid("param").name);
    const source = GITIGNORE_TEMPLATES[name];
    if (source === undefined) {
      throw new ApiError(404, "not found");
    }
    return c.json({ name, source }, 200);
  });

  // GET /label/templates — ListLabelTemplates (label_templates.go:15–30): the
  // display names of the embedded templates, sorted like LoadRepoConfig's
  // mergeCustomLabelFiles (init.go:60–75: ["Advanced", "Default"]).
  app.openapi(
    createRoute({
      method: "get",
      path: "/label/templates",
      tags: ["miscellaneous"],
      summary: "Returns a list of all label templates",
      operationId: "listLabelTemplates",
      request: {},
      responses: {
        200: {
          description: "LabelTemplateList",
          content: { "application/json": { schema: z.array(z.string()) } },
        },
      },
    }),
    (c) => c.json([...LABEL_TEMPLATE_DISPLAY_NAMES], 200),
  );

  // GET /label/templates/{name} — GetLabelTemplate (label_templates.go:32–54):
  // display-name lookup → ToLabelTemplateList (issue.go:331–339; color
  // WITHOUT the '#', exclusive_order is not part of the API model).
  app.openapi(labelTemplateInfoRoute, (c) => {
    const name = pathJoinRelX(c.req.valid("param").name);
    const template = LABEL_TEMPLATES[name];
    if (template === undefined) {
      throw new ApiError(404, "not found");
    }
    return c.json(
      template.labels.map((label) => ({
        name: label.name,
        color: label.color.replace(/^#+/, ""),
        description: label.description,
        exclusive: label.exclusive ?? false,
      })),
      200,
    );
  });

  // GET /licenses — ListLicenseTemplates (licenses.go:24–48): one
  // {key, name, url} entry per template, url = AppURL + api/v1/licenses/<escaped>.
  app.openapi(
    createRoute({
      method: "get",
      path: "/licenses",
      tags: ["miscellaneous"],
      summary: "Returns a list of all license templates",
      operationId: "listLicenseTemplates",
      request: {},
      responses: {
        200: {
          description: "LicenseTemplateList",
          content: { "application/json": { schema: z.array(licensesListEntrySchema) } },
        },
      },
    }),
    (c) => {
      const appUrl = `${new URL(c.req.url).origin}/`;
      return c.json(
        Object.keys(LICENSE_TEMPLATES).map((name) => ({
          key: name,
          name,
          url: `${appUrl}api/v1/licenses/${encodeURIComponent(name)}`,
        })),
        200,
      );
    },
  );

  // GET /licenses/{name} — GetLicenseTemplateInfo (licenses.go:50–72): the
  // fixed implementation note rides every response.
  app.openapi(licenseTemplateInfoRoute, (c) => {
    const name = pathJoinRelX(c.req.valid("param").name);
    const body = LICENSE_TEMPLATES[name];
    if (body === undefined) {
      throw new ApiError(404, "not found");
    }
    const appUrl = `${new URL(c.req.url).origin}/`;
    return c.json(
      {
        key: name,
        name,
        url: `${appUrl}api/v1/licenses/${encodeURIComponent(name)}`,
        body,
        implementation: LICENSE_IMPLEMENTATION_NOTE,
      },
      200,
    );
  });

  // POST /markup — Markup (markup.go:25–34): mode = Iif(Wiki, "wiki", Mode),
  // rendered through the shared RenderMarkup port (services/markdown.ts — the
  // unknown-mode 422 carries upstream's exact message). FilePath accepted but
  // unused (module header).
  app.openapi(
    markupRoute(requireAuth),
    async (c) => {
      const form = bindMarkupOption(await c.req.text());
      const html = renderMarkdownToHtml({
        text: form.text,
        mode: form.wiki ? "wiki" : form.mode,
        context: form.context,
        wiki: false,
        origin: new URL(c.req.url).origin,
      });
      return c.body(html, 200, { "Content-Type": HTML_CONTENT_TYPE });
    },
    markupBodyHook,
  );

  // GET /token — GetCurrentToken (token/token.go:19–52): the presented
  // credential's row (prefix lookup + digest compare mirrors getToken's
  // GetAccessTokenBySHA, token.go:75–84).
  app.openapi(currentTokenRoute(requireAuth), async (c) => {
    const row = await resolveCurrentTokenRow(c);
    // requireAuth guarantees the identity; the id-less corner (a resolved
    // identity without a D1 row) is the silent-auth-failure 401 (the follow
    // routes' viewerSlice convention).
    const doer = c.get("authUser");
    if (doer === undefined || doer.id === undefined) {
      throw new ApiError(401, "token is required");
    }
    return c.json(
      {
        id: row.id,
        name: row.name,
        scopes: row.scopes.split(","),
        created_at: row.createdAt.toISOString(),
        // upstream UpdatedUnix zero renders as the Go zero time
        // (services/repository.ts GO_ZERO_TIME convention).
        last_used_at: row.lastUsedAt === null ? GO_ZERO_TIME : row.lastUsedAt.toISOString(),
        user: { id: doer.id, login: doer.login ?? "" },
      },
      200,
    );
  });

  // DELETE /token — DeleteCurrentToken (token/token.go:55–73): delete the
  // presented credential's row, silent 204 (upstream swallows ErrNotExist).
  app.openapi(deleteCurrentTokenRoute(requireAuth), async (c) => {
    const row = await resolveCurrentTokenRow(c);
    await drizzle(c.env.DB).delete(personalAccessTokens).where(eq(personalAccessTokens.id, row.id));
    return c.body(null, 204);
  });

  // Settings — anonymous (api.go:1027–1032), static published config.
  app.openapi(generalUiSettingsRoute, (c) => c.json(GENERAL_UI_SETTINGS, 200));
  app.openapi(generalApiSettingsRoute, (c) => c.json(GENERAL_API_SETTINGS, 200));
  app.openapi(generalAttachmentSettingsRoute, (c) => c.json(GENERAL_ATTACHMENT_SETTINGS, 200));
  app.openapi(generalRepoSettingsRoute, (c) => c.json(GENERAL_REPO_SETTINGS, 200));
}

/**
 * The `/token` handlers' shared credential resolution (getToken,
 * routers/api/v1/token/token.go:75–84): parse the bearer-token header, look
 * the row up by prefix, compare digests timing-safely, and require the row to
 * belong to the authenticated doer. The token-scheme-less arm is the
 * ErrNotExist 404 (token.go:80–84) — reachable only through the production
 * `resolveAuth` identity precedence (module header).
 */
async function resolveCurrentTokenRow(c: Context<ApiEnv>) {
  const doer = c.get("authUser");
  if (doer === undefined || doer.id === undefined) {
    throw new ApiError(401, "token is required");
  }
  const presented = extractTokenHeader(c.req.header("Authorization"));
  if (presented === null) {
    throw new ApiError(404, "invalid access token");
  }
  const prefix = tokenLookupPrefix(presented);
  if (prefix === null) {
    throw new ApiError(404, "invalid access token");
  }
  const row = await drizzle(c.env.DB)
    .select()
    .from(personalAccessTokens)
    .where(eq(personalAccessTokens.prefix, prefix))
    .get();
  if (
    row === undefined ||
    row.userId !== doer.id ||
    !(await timingSafeDigestEqual(row.sha256Digest, await sha256Hex(presented)))
  ) {
    throw new ApiError(404, "invalid access token");
  }
  return row;
}

