  "Firebase": "# Firebase build and deployment files\n/firebase-debug.log\n/firebase-debug.*.log\n.firebaserc\n\n# Firebase Hosting\n/firebase.json\n*.cache\nhosting/.cache\n\n# Firebase Functions\n/functions/node_modules/\n/functions/.env\n/functions/package-lock.json\n\n# Firebase Emulators\n/firebase-*.zip\n/.firebase/\n/emulator-ui/\n\n# Logs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\n\n# Environment files (local configs)\n/.env.*\n",
  "FlaxEngine": "# Ignore Flax project files\nBinaries/\nCache/\nLogs/\nOutput/\nScreenshots/\n*.HotReload.*\n\n# Ignore Visual Studio project files (generated locally)\n*.csproj\n*.sln\n\n# Ignore thumbnails created by Windows\nThumbs.db\n\n# Ignore files built by Visual Studio\n*.obj\n*.exe\n*.pdb\n*.user\n*.aps\n*.pch\n*.vspscc\n*_i.c\n*_p.c\n*.ncb\n*.suo\n*.tlb\n*.tlh\n*.bak\n*.cache\n*.ilk\n*.log\n[Bb]in\n[Dd]ebug*/\n*.lib\n*.sbr\nobj/\n[Rr]elease*/\n_ReSharper*/\n[Tt]est[Rr]esult*\n.vs/\n\n# Ignore Nuget packages folder\npackages/\n",
