  "GitBook": "# Node rules:\n## Grunt intermediate storage (http://gruntjs.com/creating-plugins#storing-task-files)\n.grunt\n\n## Dependency directory\n## Commenting this out is preferred by some people, see\n## https://docs.npmjs.com/misc/faq#should-i-check-my-node_modules-folder-into-git\nnode_modules\n\n# Book build output\n_book\n\n# eBook build output\n*.epub\n*.mobi\n*.pdf\n",
  "GitHubPages": "# This .gitignore is appropriate for repositories deployed to GitHub Pages and using\n# a Gemfile as specified at https://github.com/github/pages-gem#conventional\n\n# Basic Jekyll gitignores (synchronize to Jekyll.gitignore)\n_site/\n.sass-cache/\n.jekyll-cache/\n.jekyll-metadata\n\n# Additional Ruby/bundler ignore for when you run: bundle install\n/vendor\n\n# Specific ignore for GitHub Pages\n# GitHub Pages will always use its own deployed version of pages-gem \n# This means GitHub Pages will NOT use your Gemfile.lock and therefore it is\n# counterproductive to check this file into the repository.\n# Details at https://github.com/github/pages-gem/issues/768\nGemfile.lock\n",
  "Go": "# If you prefer the allow list template instead of the deny list, see community template:\n# https://github.com/github/gitignore/blob/main/community/Golang/Go.AllowList.gitignore\n#\n# Binaries for programs and plugins\n*.exe\n*.exe~\n*.dll\n*.so\n*.dylib\n\n# Test binary, built with `go test -c`\n*.test\n\n# Output of the go coverage tool, specifically when used with LiteIDE\n*.out\n\n# Dependency directories (remove the comment below to include it)\n# vendor/\n\n# Go workspace file\ngo.work\ngo.work.sum\n\n# env file\n.env\n",
  "Go.AllowList": "# Allowlisting gitignore template for GO projects prevents us\n# from adding various unwanted local files, such as generated\n# files, developer configurations or IDE-specific files etc.\n#\n# Recommended: Go.AllowList.gitignore\n\n# Ignore everything\n*\n\n# But not these files...\n!/.gitignore\n\n!*.go\n!go.sum\n!go.mod\n\n!README.md\n!LICENSE\n\n# !Makefile\n\n# ...even if they are in subdirectories\n!*/\n",
  "Godot": "# Godot 4+ specific ignores\n.godot/\n\n# Godot-specific ignores\n.import/\nexport.cfg\nexport_presets.cfg\n\n# Imported translations (automatically generated from CSV files)\n*.translation\n\n# Mono-specific ignores\n.mono/\ndata_*/\nmono_crash.*.json\n",
  "Gradle": ".gradle\n**/build/\n!src/**/build/\n\n# Ignore Gradle GUI config\ngradle-app.setting\n\n# Avoid ignoring Gradle wrapper jar file (.jar files are usually ignored)\n!gradle-wrapper.jar\n\n# Avoid ignore Gradle wrapper properties\n!gradle-wrapper.properties\n\n# Cache of project\n.gradletasknamecache\n\n# Eclipse Gradle plugin generated files\n# Eclipse Core\n.project\n# JDT-specific (Eclipse Java Development Tools)\n.classpath\n",
  "Grails": "# .gitignore for Grails 1.2 and 1.3\n# Although this should work for most versions of grails, it is\n# suggested that you use the \"grails integrate-with --git\" command\n# to generate your .gitignore file.\n\n# web application files\n/web-app/WEB-INF/classes\n\n# default HSQL database files for production mode\n/prodDb.*\n\n# general HSQL database files\n*Db.properties\n*Db.script\n\n# logs\n/stacktrace.log\n/test/reports\n/logs\n\n# project release file\n/*.war\n\n# plugin release files\n/*.zip\n/plugin.xml\n\n# older plugin install locations\n/plugins\n/web-app/plugins\n\n# \"temporary\" build files\n/target\n",
  "Gretl": "# gitignore template for Gretl\n# website: http://gretl.sourceforge.net/\n\n# Auto-generated log file is overwritten whenever you start a new session\nsession.inp\n\n# Auto-generated temporary string code table\nstring_table.txt\n",
