  "IAR": "# Compiled binaries\n*.o\n*.bin\n*.elf\n*.hex\n*.map\n*.out\n*.obj\n\n# Trash\n*.bak\nthumbs.db\n*.~*\n\n# IAR Settings  \n**/settings/*.crun  \n**/settings/*.dbgdt  \n**/settings/*.cspy  \n**/settings/*.cspy.*  \n**/settings/*.xcl  \n**/settings/*.dni  \n**/settings/*.wsdt  \n**/settings/*.wspos  \n\n# IAR Debug Exe  \n**/Exe/*.sim  \n\n# IAR Debug Obj  \n**/Obj/*.pbd  \n**/Obj/*.pbd.*  \n**/Obj/*.pbi  \n**/Obj/*.pbi.*  \n\n# IAR project \"Debug\" directory\nDebug/\n\n# IAR project \"Release\" directory\nRelease/\n\n# IAR project settings directory\nsettings/\n\n# IAR backup files\nBackup*\n\n# IAR .dep files\n*.dep",
  "IAR_EWARM": "# gitignore template for the IAR EWARM\n# website: https://www.iar.com/knowledge/support/technical-notes/ide/which-files-should-be-version-controlled/\n\n# Some tools will put the EWARM files\n# under a subdirectory with the same name\n# as the configuration.\n# Example\n# EWARM/Config1/Obj /List /Exe\n# EWARM/Config2/Obj /List /Exe\nEWARM/**/Obj\nEWARM/**/List\nEWARM/**/Exe\n\n# Autogenerated project files\n*.dep\n*.ewt\n\n# Autogenerated folder for debugger\nEWARM/settings\n",
